1	import SpeedOutlined from '@mui/icons-material/SpeedOutlined'
2	import { Button } from '@mui/material'
3	import { useEffect, useState, type MouseEvent } from 'react'
4	import { useClaudeRateLimits } from '../hooks/use_claude_rate_limits'
5	import { ClaudeRateLimitDetails } from './claude_rate_limit_details'
6	import { claudeRateLimitPresentation } from './claude_rate_limit_status_data'
7	import { MobileStatusRow } from './mobile_status_row'
8	import { StatusDetailsSurface } from './status_details_surface'
9	
10	const RESET_CLOCK_UPDATE_INTERVAL_MS = 30_000
11	
12	interface ClaudeRateLimitStatusProps {
13	    mobile?: boolean
14	}
15	
16	/** Account-wide Claude rate-limit status. Own subscription stays at this leaf boundary. */
17	export function ClaudeRateLimitStatus({ mobile = false }: ClaudeRateLimitStatusProps) {
18	    const rateLimitState = useClaudeRateLimits()
19	    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
20	    const [currentTime, setCurrentTime] = useState(Date.now)
21	
22	    useEffect(() => {
23	        const interval = setInterval(() => setCurrentTime(Date.now()), RESET_CLOCK_UPDATE_INTERVAL_MS)
24	
25	        return () => clearInterval(interval)
26	    }, [])
27	
28	    const presentation = claudeRateLimitPresentation(rateLimitState)
29	    if (!presentation) return null
30	    const { accessibleState, highestUsedPercent, nearLimit, reached, receivedAt, snapshot } = presentation
31	    const statusColor = reached ? 'error.main' : nearLimit ? 'warning.main' : 'text.secondary'
32	    const roundedHighestPercent = Math.round(highestUsedPercent)
33	    const openDetails = (event: MouseEvent<HTMLElement>) => {
34	        setAnchorElement(event.currentTarget)
35	    }
36	    const closeDetails = () => {
37	        setAnchorElement(null)
38	    }
39	    const accessibleName = `Claude usage ${roundedHighestPercent}% used${accessibleState}`
40	
41	    return (
42	        <>
43	            {mobile ? (
44	                <MobileStatusRow
45	                    accessibleName={accessibleName}
46	                    icon={<SpeedOutlined sx={{ fontSize: 18 }} />}
47	                    label="Claude usage"
48	                    onClick={openDetails}
49	                    tone={statusColor}
50	                    value={`${roundedHighestPercent}% used`}
51	                />
52	            ) : (
53	                <Button
54	                    aria-label={accessibleName}
55	                    onClick={openDetails}
56	                    size="small"
57	                    startIcon={<SpeedOutlined sx={{ fontSize: 14 }} />}
58	                    sx={{ color: statusColor, fontSize: 'inherit', minWidth: 0, p: 0.5, whiteSpace: 'nowrap' }}
59	                >
60	                    Claude {roundedHighestPercent}% used
61	                </Button>
62	            )}
63	            <StatusDetailsSurface anchorElement={anchorElement} labelId="claude-rate-limit-title" mobile={mobile} onClose={closeDetails}>
64	                <ClaudeRateLimitDetails
65	                    currentTime={currentTime}
66	                    reached={reached}
67	                    receivedAt={receivedAt}
68	                    snapshot={snapshot}
69	                />
70	            </StatusDetailsSurface>
71	        </>
72	    )
73	}
